# Content for the free money guides. Each guide = steps with copyable Claude prompts + an "agent" setup.
G = {}
G["credit"] = dict(
 kw="CREDIT", title="Fix your credit report yourself", sub="Find errors on your credit reports and dispute them, with Claude doing the heavy lifting. No credit repair company needed.",
 time="About 30 minutes", need="Your 3 credit reports (free) and Claude",
 why="Errors on credit reports are common, and an error can raise what you pay for loans, cards, insurance and even apartments. You have the legal right to dispute anything that's wrong, for free.",
 steps=[
  ("Get all 3 reports, free", "Go to AnnualCreditReport.com, the only official free site. You can pull your Equifax, Experian and TransUnion reports every week at no cost. Download each one as a PDF. Reports don't show your score, and that's fine: the report is what you fix.", None, [("AnnualCreditReport.com","https://www.annualcreditreport.com")]),
  ("Black out the sensitive stuff", "Before uploading anywhere, cover your Social Security number and full account numbers. Claude doesn't need them to find errors. The last 4 digits are enough to tell accounts apart.", None, []),
  ("Have Claude audit all 3 reports", "Upload the three PDFs to Claude in one chat and paste this:", "I uploaded my credit reports from Equifax, Experian and TransUnion. Go through them carefully and make a table of anything that could be wrong or hurting me: accounts I might not recognize, wrong balances or limits, late payments, duplicate accounts or collections, items that look older than 7 years, paid or under $500 medical collections, and anything that's different between the three bureaus. For each one, tell me: the bureau, what looks wrong, why it matters, and what proof I would need. Then ask me which items are actually errors before suggesting what to dispute.", []),
  ("Dispute only what's actually wrong", "Go through Claude's table and confirm what's truly inaccurate. Then dispute it with the bureau that shows it. Online is fastest. The bureau generally has to investigate within 30 days (up to 45 in some cases). Have Claude write the dispute so it's clear and specific:", "Write a credit report dispute for [Equifax / Experian / TransUnion]. The item: [creditor name, last 4 digits, what it shows]. What is wrong: [your facts]. Proof I have: [statements, letters, payment confirmations]. Keep it short, factual and polite. Ask them to investigate and correct or delete the item under the Fair Credit Reporting Act, and list what I'm enclosing.", [("Equifax disputes","https://www.equifax.com/personal/credit-report-services/credit-dispute/"),("Experian disputes","https://www.experian.com/disputes/main.html"),("TransUnion disputes","https://www.transunion.com/credit-disputes/dispute-your-credit")]),
  ("Handle the true negatives the smart way", "Accurate negatives can't be disputed away, and nobody can legally remove them for you. But you can still ask. For a one time late payment on an account that's otherwise good, a goodwill letter sometimes works:", "Write a short goodwill letter to [creditor]. I've been a customer since [year]. I paid late in [month, year] because [honest reason]. I've paid on time since. Politely ask if they would consider removing the late payment from my credit reports as a goodwill gesture. No excuses, no demands.", []),
  ("Raise your score while disputes run", "Two things move your score most: paying on time, and how much of your card limits you're using. Set every card to autopay at least the minimum, and work balances down. Have Claude plan it:", "Here are my cards with balance, limit, APR and minimum: [list]. I can put $[amount] a month toward them. Make a month by month plan that lowers my credit utilization fastest and saves the most interest. Show the utilization on each card each month.", []),
  ("If a dispute goes nowhere", "If the bureau won't fix a clear error, you can file a complaint with the Consumer Financial Protection Bureau. Ask Claude to write it from your notes and proof.", None, [("CFPB complaint","https://www.consumerfinance.gov/complaint/")]),
 ],
 warn=["Only dispute information that is actually wrong. Disputing accurate items as false can backfire.","Credit repair companies can't legally charge you before doing the work, and they can't remove accurate information. Everything they do, you can do yourself for free.","Most negative items drop off on their own after about 7 years."],
 agent=dict(name="Credit Agent", what="A Claude Project that remembers your reports, your disputes and their deadlines, and checks in every month.",
  setup=["In Claude, create a new Project and name it Credit Agent.","Paste the instructions below into the Project's instructions.","Upload your redacted reports and Claude's audit table to the Project's files.","Once a month: pull fresh reports, drop them in, and type: monthly check."],
  instr="You are my Credit Agent. Your job: keep my credit reports accurate and help me raise my score. You have my redacted reports and my dispute log in the project files. Every time I say 'monthly check': compare the newest reports to the last ones, list anything new or changed, update the dispute log (item, bureau, date sent, 30 day deadline, status), tell me which disputes are overdue and draft follow ups, and give me my one most useful action this month. Only suggest disputing items I confirm are wrong. Keep answers short, with a table and a single next step."),
 sources=[("FTC: Credit repair, how to help yourself","https://consumer.ftc.gov/articles/disputing-errors-your-credit-reports"),("CFPB: credit reports and scores","https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/")],
)
G["bill"] = dict(
 kw="BILL", title="Cut a medical bill before you pay it", sub="Medical bills often have errors and there's often help available. Here's how to check yours and ask the right questions, with Claude.",
 time="About 30 minutes, plus a phone call", need="The bill, your insurance's Explanation of Benefits (EOB), and Claude",
 why="A medical bill is a starting point, not a final answer. You can ask for the details, question errors, apply for financial assistance and set up a payment plan.",
 steps=[
  ("Don't pay the summary bill yet", "Call the billing office and ask for an itemized bill with every charge and its billing code. Also log into your insurance and download the Explanation of Benefits (EOB) for that visit.", None, []),
  ("Black out what Claude doesn't need", "Cover your member ID, date of birth and account numbers before uploading.", None, []),
  ("Have Claude audit the bill", "Upload the itemized bill and the EOB, then paste this:", "I uploaded an itemized medical bill and my insurance Explanation of Benefits for the same visit. Compare them line by line. Find: duplicate charges, services that look like they didn't happen or don't match the visit, charges insurance should have covered or adjusted, amounts that differ between the bill and the EOB, and anything I should ask about. Make a table: line item, amount, what looks wrong, the question to ask. Explain billing codes in plain English. Don't assume, flag what needs checking.", []),
  ("Ask about financial assistance", "Most nonprofit hospitals are required to have a written financial assistance policy, and many people qualify without knowing it. Have Claude prep the call:", "Write me a short, friendly phone script to call [hospital] billing. I want to: ask if they have a financial assistance or charity care program and how to apply, ask about the line items I flagged [paste list], and ask for a no interest payment plan if I still owe money. Include what to say if they say no, and a list of things to write down during the call (name, date, reference number).", []),
  ("Negotiate what's left", "If you'll pay some of it, ask for a discount for paying in full or a payment plan you can actually afford. Get any agreement in writing.", "Write a short email to [hospital or provider] billing. Account ending in [last 4]. After reviewing my itemized bill I'm requesting: corrections on [items], a review for financial assistance, and [a discount for paying in full / a payment plan of $X per month]. Ask them to confirm any agreement in writing.", []),
  ("Know the credit rules", "The three credit bureaus don't include paid medical collections or medical collections under $500 on credit reports, and new medical debt isn't reported for a year. If you see one of these on your report, you can dispute it.", None, [("AnnualCreditReport.com","https://www.annualcreditreport.com")]),
  ("Surprise bills", "Federal law protects you from many surprise out of network bills, like emergency care, and gives self pay patients the right to a good faith estimate before care.", None, [("CMS: No Surprises","https://www.cms.gov/nosurprises")]),
 ],
 warn=["Claude helps you find questions to ask. The billing office and your insurer have the final word, so confirm everything with them.","Don't ignore a bill while you're reviewing it. Call and tell them it's under review.","Never share full insurance or card numbers in a chat."],
 agent=dict(name="Bill Agent", what="A Claude Project that checks every medical bill against your insurance before you pay, and tracks every call.",
  setup=["Create a new Claude Project named Bill Agent.","Paste the instructions below.","Upload your insurance plan summary (deductible, copays, out of pocket max) to the Project's files.","Every new bill: upload the itemized bill and EOB and type: check this bill."],
  instr="You are my Bill Agent. When I say 'check this bill', compare the itemized bill to the EOB and my plan summary, list possible errors and questions in a table, tell me how much I should actually owe based on my plan, and write the call script and follow up email. Keep a log of every bill (provider, date, amount billed, amount owed, status, call notes). Never tell me to pay before the review is done. Keep it short and clear."),
 sources=[("CFPB: medical billing and collections","https://www.consumerfinance.gov/consumer-tools/debt-collection/"),("CMS: No Surprises Act","https://www.cms.gov/nosurprises")],
)
G["debt"] = dict(
 kw="DEBT", title="Lower your interest and get out of card debt", sub="Ask for a lower rate, then follow a payoff plan built around your real numbers. Claude writes the script and does the math.",
 time="About 20 minutes, plus a few calls", need="Your card statements and Claude",
 why="Card interest is one of the most expensive things in most budgets. A lower rate and the right payoff order can save real money and months of payments.",
 steps=[
  ("List every debt", "Grab your latest statements. Black out full account numbers, then upload them or type the numbers in:", "Here are my debts with balance, APR and minimum payment: [list, or see uploaded statements]. Put them in a clean table. Show the total I owe, the total minimums, and roughly how much interest I'm paying each month on each one.", []),
  ("Call and ask for a lower rate", "It doesn't always work, but the call takes a few minutes and some people get a lower rate just by asking, especially with a good payment history. Also ask if they have a hardship program. Let Claude write your script:", "Write me a confident, polite phone script to ask [card company] for a lower APR. Facts: customer since [year], I [have / haven't] paid on time, my current APR is [X]%. Include: the opening ask, what to say if they say no (ask for a supervisor, ask about a temporary rate or hardship program), and what to write down. Keep it natural, not pushy.", []),
  ("Pick your payoff order", "Avalanche pays the highest APR first and usually saves the most interest. Snowball pays the smallest balance first for quick wins. Claude can show you both with your numbers:", "Using my debts above and $[amount] a month total to pay them, show me two plans: avalanche (highest APR first) and snowball (smallest balance first). For each: the payoff month for every debt, total interest paid, and the debt free date. Then tell me the difference in plain English.", []),
  ("Find extra money for the plan", "Upload one or two months of bank statements (account numbers blacked out):", "Look through these statements and find money I could redirect to debt: subscriptions, repeat fees, things I'm paying for twice, and my biggest spending categories. Give me the top 5 changes with how much each frees up per month. Be realistic, not extreme.", []),
  ("Be careful with quick fixes", "Balance transfer cards usually charge a transfer fee and the low rate ends on a set date. Debt settlement companies can hurt your credit and charge big fees. If you're overwhelmed, a nonprofit credit counselor can help you look at a debt management plan.", None, [("NFCC nonprofit counseling","https://www.nfcc.org"),("FTC: debt relief scams","https://consumer.ftc.gov/articles/how-get-out-debt")]),
 ],
 warn=["This is education, not financial advice. Check the numbers on your actual statements.","Never pay anyone upfront to settle or erase your debt.","Keep paying at least the minimum on everything while you work the plan."],
 agent=dict(name="Debt Agent", what="A Claude Project that tracks every balance, keeps your payoff plan current and tells you exactly what to pay each month.",
  setup=["Create a new Claude Project named Debt Agent.","Paste the instructions below.","Add your debt table and chosen plan to the Project's files.","After each payday or statement: type your new balances and say: update my plan."],
  instr="You are my Debt Agent. You have my debts and my chosen payoff plan in the project files. When I say 'update my plan', take my new balances, recalculate the plan, tell me exactly how much to pay on each debt this month, show progress (total paid off, interest saved vs minimums, new debt free date), and flag anything off track. Celebrate each debt that hits zero. Keep it short: a table, the payment list, one sentence of encouragement."),
 sources=[("CFPB: debt and credit tools","https://www.consumerfinance.gov/consumer-tools/credit-cards/"),("FTC: how to get out of debt","https://consumer.ftc.gov/articles/how-get-out-debt")],
)
